/**
 * Unit tests for TextBuffer.getTextBuffer().
 * Goal: Maximize branch and line coverage.
 */
public class TextBuffer_getTextBuffer_TriageGen2Test {

    private BufferRecycler recycler;
    private TextBuffer textBuffer;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }



    @Test
    public void testGetTextBuffer_ResultArray() {
        // To reach the (_resultArray != null) branch, we need to trigger a state 
        // where _inputStart < 0 and _resultArray is already populated.
        // This happens after a segment is finished or via contentsAsArray.

        textBuffer.append('h');
        textBuffer.append('i');
        // finishCurrentSegment moves content to _resultArray (or makes it non-shared)
        textBuffer.finishCurrentSegment();

        // Ensure _inputStart is < 0 (default state for new/reset buffers)
        // In Jackson's TextBuffer, after finishing segments, it's no longer shared.
        char[] result1 = textBuffer.getTextBuffer();
        char[] result2 = textBuffer.getTextBuffer();

        Assert.assertNotNull(result1);
        Assert.assertSame("Should return the same cached _resultArray", result1, result2);
    }






}

