/**
 * Unit tests for TextBuffer.getTextBuffer().
 * Goal: Maximize branch and line coverage.
 */
public class TextBuffer_getTextBuffer_TriageGen2Test {

    private BufferRecycler recycler;
    private TextBuffer textBuffer;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }





    @Test
    public void testGetTextBuffer_ResultString() {
        // To reach the (_resultString != null) branch, we use resetWithString.
        // resetWithString sets _resultString and clears other buffers.
        String input = "hello";
        textBuffer.resetWithString(input);

        char[] result = textBuffer.getTextBuffer();

        Assert.assertArrayEquals(input.toCharArray(), result);

        // Verify that _resultArray is now cached by calling it again
        char[] result2 = textBuffer.getTextBuffer();
        Assert.assertSame("Should cache the char array from the string", result, result2);
    }




}

