import java.util.Arrays;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TextBuffer.getTextBuffer().
 * Goal: Maximize branch and line coverage.
 */
public class TextBuffer_getTextBuffer_TriageGen2Test {

    private BufferRecycler recycler;
    private TextBuffer textBuffer;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }









    @Test
    public void testGetTextBuffer_ContentsAsArray() {
        // To reach the final return contentsAsArray():
        // This happens if _hasSegments is true, but _inputStart < 0 and _resultArray is null.

        textBuffer.append('a');
        textBuffer.append('b');
        // Force _hasSegments to true by finishing the segment
        textBuffer.finishCurrentSegment();

        // After finishCurrentSegment, if we haven't accessed the buffer via getTextBuffer yet,
        // we need to ensure we hit the logic for a non-segmented array.
        // Actually, finishCurrentSegment usually populates _resultArray.
        // To force the 'contentsAsArray' fallback, we simulate a state where 
        // segments exist but we are asking for the array.

        // If we manually append enough to trigger multiple segments:
        for (int i = 0; i < 100; i++) {
            textBuffer.append((char) i);
        }

        char[] result = textBuffer.getTextBuffer();
        Assert.assertNotNull(result);
        Assert.assertTrue(result.length > 0);
    }
}
